import unittest
from solution import freq_table

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(freq_table("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(freq_table("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(freq_table(""), {})
    def test_whitespace(self):
        self.assertEqual(freq_table("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(freq_table("solo"), {"solo": 1})
